import requests

from hran_pacman.bases.wft_base import WFTDownloader
from hran_pacman.bases.logger import LOGGER
from hran_pacman.exceptions import InvalidBuildException


class LtePackageDownloader(WFTDownloader):
    technology = "LTE"

    @property
    def package_name(self):
        return "{}{}.zip".format(self.baseline, "_release_BTSSM_downloadable")

    @property
    def downloadable_name(self):
        return "downloadable.zip"

    def get_site_manager(self):
        """
        Method downloads BTS Site Manager to current working directory
        """
        try:
            response = requests.get(self.sem_url_base.format(version=self.site_manager_baseline), stream=True,
                                    verify=False)
            name = self.site_manager_baseline + ".zip"
            self._stream_to_file(name, response)
        except InvalidBuildException:
            LOGGER.debug("Could not determine Site Manager baseline")
